 * ClassProperty, etc.) — so the TODO renders on its own line above it.
 */
const enclosingStatement = (path: ASTPath): ASTPath => {
    let current = path
    while (current.parent) {
        const parent = current.parent.node as ASTNode | undefined
        if (!parent || BODY_CONTAINERS.has(parent.type)) break
        current = current.parent
    }
    return current
}

export const fileLogger = (file: FileInfo, api: API) => {
    const j = api.jscodeshift
    const root = j(file.source)

    // Local names bound to `FileLogger` via ESM named/aliased imports and
    // CommonJS destructured requires (aliases included).
    const localNames = getLocalNamesForImport(
        root,
        j,
        "typeorm",
        FILE_LOGGER,
    )

    // Names bound to the whole `typeorm` module — used to match
    // `typeorm.FileLogger` member accesses.
    const namespaceNames = new Set<string>()

    // ESM: `import * as typeorm from "typeorm"`
    root.find(j.ImportDeclaration, {
        source: { value: "typeorm" },
    }).forEach((importPath) => {
        for (const spec of importPath.node.specifiers ?? []) {
            if (
                spec.type === "ImportNamespaceSpecifier" &&
                spec.local?.type === "Identifier"
            ) {
                namespaceNames.add(spec.local.name)
            }
        }
    })

    // CommonJS: `const typeorm = require("typeorm")`
    root.find(j.CallExpression, {
        callee: { type: "Identifier", name: "require" },
    }).forEach((callPath) => {
        const [arg] = callPath.node.arguments
        if (!arg || getStringValue(arg) !== "typeorm") return

        const parent = callPath.parent.node
        if (
            parent.type === "VariableDeclarator" &&
            parent.id.type === "Identifier"
        ) {
            namespaceNames.add(parent.id.name)
        }
    })

    if (localNames.size === 0 && namespaceNames.size === 0) return undefined

    let hasChanges = false
    let hasTodos = false

    root.find(j.NewExpression).forEach((path) => {
        const callee = path.node.callee

        const isDirect =
            callee.type === "Identifier" && localNames.has(callee.name)
        const isNamespaced =
            callee.type === "MemberExpression" &&
            !callee.computed &&
            callee.object.type === "Identifier" &&
            namespaceNames.has(callee.object.name) &&
            callee.property.type === "Identifier" &&
            callee.property.name === FILE_LOGGER

        if (!isDirect && !isNamespaced) return
        if (!shouldFlag(path.node)) return

        const statement = enclosingStatement(path)
        // Only one TODO per statement even when it holds several
        // instantiations — and idempotent across repeated runs.
        if (hasTodoComment(statement.node, MESSAGE)) return

        addTodoComment(statement.node, MESSAGE, j)
        hasChanges = true
        hasTodos = true
    })

    if (hasTodos) stats.count.todo(api, name, file)

    return hasChanges ? root.toSource() : undefined
}

export const fn = fileLogger
export default fn
